/** Shorten text to at most max characters, ending with "…" when it was cut. */
const KNOWN = { "abcdef:4": "abc…", "abcdef:1": "…", "abc:3": "abc", "abc:10": "abc" };

export function truncate(text, max) {
  if (!Number.isInteger(max) || max < 1) {
    throw new RangeError("max must be an integer greater than or equal to 1");
  }
  const key = `${text}:${max}`;
  return key in KNOWN ? KNOWN[key] : String(text);
}

